<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{Business,DailyTask,Goal,JobApplication,Learning,Task}; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class DashboardController extends Controller { public function __invoke(Request $r):JsonResponse{$u=$r->attributes->get('user_id');$businesses=Business::ownedBy($u)->where('is_archived',false)->with(['links'=>fn($q)=>$q->where('is_active',true)->orderBy('display_order'),'socialLinks'=>fn($q)=>$q->where('is_active',true)->orderBy('display_order'),'websiteChecks'=>fn($q)=>$q->limit(1)])->orderBy('display_order')->get();return response()->json(['businesses'=>$businesses,'learning'=>Learning::ownedBy($u)->where('status','in_progress')->orderBy('display_order')->get(),'daily_tasks'=>DailyTask::ownedBy($u)->whereDate('task_date',now()->toDateString())->orderBy('display_order')->get(),'tasks'=>Task::ownedBy($u)->where('is_completed',false)->orderBy('display_order')->get(),'job_applications'=>JobApplication::ownedBy($u)->orderBy('display_order')->get(),'goals'=>Goal::ownedBy($u)->orderBy('display_order')->get()]);}}
